CREATE OR REPLACE FUNCTION public.confirm_voucher_item(iid uuid,rid uuid,res text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; i voucher_items; b voucher_batches; BEGIN IF res NOT IN ('ok','error') THEN RAISE EXCEPTION 'invalid_result'; END IF; PERFORM pg_advisory_xact_lock(hashtext(rid::text)); SELECT * INTO i FROM voucher_items WHERE id=iid AND router_id=rid AND state='sent' FOR UPDATE; IF i.id IS NULL THEN RETURN; END IF; SELECT * INTO b FROM voucher_batches WHERE id=i.batch_id; UPDATE voucher_items SET state=CASE WHEN res='ok' THEN 'confirmed' ELSE 'failed' END,result=res WHERE id=iid; IF res='ok' THEN INSERT INTO router_cards(router_id,source,name,profile,limit_uptime_s,limit_bytes,pw_mode,synced_at) VALUES(rid,i.source,i.name,b.package_name,CASE WHEN i.source='hotspot' THEN (b.package_snapshot->'issue_limits'->>'time')::bigint ELSE NULL END,CASE WHEN i.source='hotspot' THEN (b.package_snapshot->'issue_limits'->>'bytes')::bigint ELSE NULL END,CASE WHEN b.mode='different' THEN 'other' ELSE b.mode END,now()) ON CONFLICT(router_id,source,name) DO NOTHING; END IF; IF NOT EXISTS(SELECT 1 FROM voucher_items WHERE batch_id=i.batch_id AND state IN ('pending','sent')) THEN UPDATE voucher_batches SET state='complete' WHERE id=i.batch_id; END IF; END $$;
REVOKE ALL ON FUNCTION public.confirm_voucher_item(uuid,uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.confirm_voucher_item(uuid,uuid,text) TO service_role;